const $ = (selector) => document.querySelector(selector);
const trialsSelect = $('#trial-count'), symmetrySelect = $('#symmetry'), runButton = $('#run-simulation'), stopButton = $('#stop-simulation'), status = $('#simulation-status'), histogram = $('#histogram'), samples = $('#sample-grids'), summary = $('#tally-summary');
const shuffled = (values) => { const copy = [...values]; for (let i = copy.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [copy[i], copy[j]] = [copy[j], copy[i]]; } return copy; };
const boxIndex = (row, column) => Math.floor(row / 3) * 3 + Math.floor(column / 3);
const digitsFromMask = (mask) => shuffled([1,2,3,4,5,6].filter((digit) => !(mask & (1 << digit))));

function makePattern(symmetric) {
  const pattern = Array.from({ length: 9 }, () => Array(9).fill(false));
  if (!symmetric) {
    for (let band = 0; band < 3; band++) { const order = [shuffled([0,1,2]), shuffled([0,1,2]), shuffled([0,1,2])], rows = shuffled([0,1,2]), perms = shuffled([[0,1,2],[1,2,0],[2,0,1]]); for (let local = 0; local < 3; local++) for (let stack = 0; stack < 3; stack++) pattern[band * 3 + local][stack * 3 + order[stack][perms[rows[local]][stack]]] = true; }
    return pattern;
  }
  const mirrorSum = Math.floor(Math.random() * 3), first = Math.floor(Math.random() * 3), stacks = [first, (mirrorSum * 2) % 3, (mirrorSum - first + 3) % 3], rows = Array(9), complement = (2 - mirrorSum + 3) % 3, top = shuffled([0,1,2]);
  for (let row = 0; row < 3; row++) { rows[row] = top[row]; rows[8 - row] = (complement - top[row] + 3) % 3; }
  const middle = (complement * 2) % 3, choices = shuffled([0,1,2].filter((value) => value !== middle)); rows[3] = choices[0]; rows[4] = middle; rows[5] = choices[1];
  for (let row = 0; row < 9; row++) for (let stack = 0; stack < 3; stack++) pattern[row][stack * 3 + (rows[row] + stacks[stack]) % 3] = true;
  return pattern;
}
function solve(pattern, givens, limit = 1) {
  const values = givens.map((row) => [...row]), rowUsed = Array(9).fill(0), colUsed = Array(9).fill(0), boxUsed = Array(9).fill(0), open = [];
  for (let r = 0; r < 9; r++) for (let c = 0; c < 9; c++) { if (pattern[r][c]) continue; const b = boxIndex(r,c), value = values[r][c]; if (value) { const flag = 1 << value; if ((rowUsed[r] | colUsed[c] | boxUsed[b]) & flag) return { count: 0, values: null }; rowUsed[r] |= flag; colUsed[c] |= flag; boxUsed[b] |= flag; } else open.push({r,c,b}); }
  let count = 0, first = null;
  function search(cells) { if (count >= limit) return; if (!cells.length) { count++; first ??= values.map((row) => [...row]); return; } let choice = -1, options; cells.forEach((cell,index) => { const found = digitsFromMask(rowUsed[cell.r] | colUsed[cell.c] | boxUsed[cell.b]); if (!options || found.length < options.length) { choice = index; options = found; } }); if (!options.length) return; const cell = cells[choice], next = cells.filter((_, index) => index !== choice); for (const digit of options) { const flag = 1 << digit; values[cell.r][cell.c] = digit; rowUsed[cell.r] |= flag; colUsed[cell.c] |= flag; boxUsed[cell.b] |= flag; search(next); values[cell.r][cell.c] = null; rowUsed[cell.r] &= ~flag; colUsed[cell.c] &= ~flag; boxUsed[cell.b] &= ~flag; if (count >= limit) return; } }
  search(open); return { count, values: first };
}
function generatePuzzle(symmetric) { for (let attempt = 0; attempt < 100; attempt++) { const pattern = makePattern(symmetric), blank = Array.from({length:9}, () => Array(9).fill(null)), solution = solve(pattern, blank).values; if (!solution) continue; const dug = solution.map((row) => [...row]); for (const index of shuffled(Array.from({length:81},(_,i)=>i).filter((i)=>!pattern[Math.floor(i/9)][i%9]))) { const r = Math.floor(index/9), c = index % 9, digit = dug[r][c]; dug[r][c] = null; if (solve(pattern, dug, 2).count !== 1) dug[r][c] = digit; } return {pattern, dug}; } throw Error('Could not generate a puzzle'); }
function renderSample({pattern, dug}, number) { const card = document.createElement('article'), clues = dug.flat().filter(Boolean).length; card.className = 'sample-grid-card'; card.innerHTML = `<div class="sample-topline"><span>Final puzzle ${number}</span><span>${clues} clues</span></div>`; const grid = document.createElement('div'); grid.className = 'grid'; pattern.flat().forEach((shaded,index) => { const r = Math.floor(index/9), c = index % 9, cell = document.createElement('div'), empty = !shaded && !dug[r][c]; cell.className = `cell${shaded?' shaded':''}${empty?' empty':''}${c%3===2?' box-right':''}${r%3===2?' box-bottom':''}`; if (!shaded && !empty) cell.textContent = dug[r][c]; grid.append(cell); }); card.append(grid); return card; }
let running = false, completed = 0, total = 0, duration = 0, tallies = new Map(), latest = [];
function renderResults() { const max = Math.max(...tallies.values(),1); histogram.replaceChildren(); [...tallies.entries()].sort(([a],[b])=>a-b).forEach(([tally,count])=>{ const bar=document.createElement('div'); bar.className='histogram-bar'; bar.style.setProperty('--bar-height',`${Math.max(7,count/max*100)}%`); bar.innerHTML=`<span class="bar-count">${count}</span><div class="bar-fill" title="${tally} clues: ${count} puzzles"></div><span class="bar-label">${tally}</span>`; histogram.append(bar); }); const generated = [...tallies.values()].reduce((sum,count)=>sum+count,0), mean = generated ? [...tallies.entries()].reduce((sum,[tally,count])=>sum+tally*count,0)/generated : 0; summary.textContent = generated ? `${generated.toLocaleString()} puzzles · mean ${mean.toFixed(1)} clues · ${(duration/generated).toFixed(1)} ms/puzzle` : 'No puzzles yet'; samples.replaceChildren(...latest.map((puzzle,index)=>renderSample(puzzle,completed-index))); }
function finish(message) { running=false; runButton.disabled=false; stopButton.disabled=true; trialsSelect.disabled=false; symmetrySelect.disabled=false; status.textContent=message; }
function runBatch() { if (!running) return; const started=performance.now(); do { const one=performance.now(), puzzle=generatePuzzle(symmetrySelect.value==='true'); duration += performance.now()-one; const clues=puzzle.dug.flat().filter(Boolean).length; tallies.set(clues,(tallies.get(clues)??0)+1); latest.unshift(puzzle); latest=latest.slice(0,8); completed++; } while(running && completed<total && performance.now()-started<40); renderResults(); if(completed>=total) { finish(`Complete — ${completed.toLocaleString()} unique, irreducible puzzles generated.`); return; } status.textContent=`Generating… ${completed.toLocaleString()} of ${total.toLocaleString()} complete · ${(duration/completed).toFixed(1)} ms/puzzle.`; requestAnimationFrame(runBatch); }
runButton.addEventListener('click',()=>{ total=Number(trialsSelect.value); completed=0; duration=0; tallies=new Map(); latest=[]; running=true; runButton.disabled=true; stopButton.disabled=false; trialsSelect.disabled=true; symmetrySelect.disabled=true; status.textContent='Generating uniquely dug puzzles…'; renderResults(); requestAnimationFrame(runBatch); }); stopButton.addEventListener('click',()=>finish(`Stopped after ${completed.toLocaleString()} trials.`));
